insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('torquedrag', 'intermediate', 'module', 'm01-the-friction-factor', 1, 'What is the difference between a friction factor and a coefficient of friction?', '["There is no difference in practice.", "A coefficient is a material property measurable in a laboratory; a factor is a fitting parameter.", "A coefficient applies to sliding contact and a factor to rolling contact, which is what a rotating tool joint makes.", "A coefficient is dimensionless and a factor carries the units of the normal force it multiplies in the model."]'::jsonb, 1, 'They have the same units and enter the same equation, and only one of them is a statement about two materials.'),
  ('torquedrag', 'intermediate', 'module', 'm01-the-friction-factor', 2, 'Which of these does the friction factor NOT absorb?', '["The buoyancy of the string in the mud.", "Cuttings beds in an inclined hole.", "The bending stiffness the soft-string model discarded, which a real string develops when it bridges a dogleg.", "A survey that does not describe the hole accurately, including tortuosity between the surveyed stations."]'::jsonb, 0, 'Buoyancy is computed explicitly from the two densities. Everything else the model cannot see lands in the factor.'),
  ('torquedrag', 'intermediate', 'module', 'm01-the-friction-factor', 3, 'Why is a rising friction factor over a few days usually not about the rock?', '["Because the factor is a constant of the model.", "Because rock friction is measured before drilling and entered as a fixed input rather than fitted during the well.", "Because the rock did not change; the hole condition, the cuttings or the sticking did.", "Because a rising factor always indicates an instrument drift in the weight indicator rather than a downhole change."]'::jsonb, 2, 'That is why the TREND is informative even though the VALUE is not a material property.'),
  ('torquedrag', 'intermediate', 'module', 'm01-the-friction-factor', 4, 'What are typical open-hole friction factors in water-based mud?', '["About 0.05 to 0.10.", "About 0.6 to 0.9, which reflects the roughness of an uncased hole with a filter cake on the wall.", "There are no typical values, since the factor is fitted per well and no distribution has been published.", "About 0.25 to 0.40."]'::jsonb, 3, 'In oil-based mud the range drops to roughly 0.15 to 0.30, which is often the difference between a drillable well and one that is not.'),
  ('torquedrag', 'intermediate', 'module', 'm01-the-friction-factor', 5, 'Where do the published typical values come from?', '["Laboratory tribometer measurements.", "Back-analysis of thousands of wells, so they are the distribution of a fitted parameter.", "A theoretical derivation from the surface roughness of steel against rock at the contact pressures involved.", "An API standard that specifies them by hole condition and requires their use in any submitted well plan."]'::jsonb, 1, 'That is a respectable provenance and it is worth knowing it is the provenance, because it makes the values a prior rather than a prediction.'),
  ('torquedrag', 'intermediate', 'module', 'm01-the-friction-factor', 6, 'Why is open hole a higher factor than casing?', '["Rock with a filter cake is rougher than steel, it accumulates cuttings, and it can have ledges.", "Because casing is lubricated.", "Because the cased section is always in the vertical part of the well, where the side force is lower.", "Because casing is larger in diameter, so the same string presses against it with a smaller contact pressure."]'::jsonb, 0, 'The three reasons are in decreasing order of size, and the first one alone does not account for the whole difference.'),
  ('torquedrag', 'intermediate', 'module', 'm01-the-friction-factor', 7, 'Which factor matters more, cased or open hole, on a well whose shoe is in the vertical section?', '["The cased one, being applied first.", "The open-hole one, because it acts over a longer interval, though the cased one still contributes about a fifth.", "Neither: the cased factor is multiplying a side force of zero.", "Both equally, since the friction factor is applied to every metre of string in each section regardless of geometry."]'::jsonb, 2, 'Set the cased factor to zero on the horizontal well and nothing changes. Before caring about a factor, find out what side force it multiplies.'),
  ('torquedrag', 'intermediate', 'module', 'm01-the-friction-factor', 8, 'How does the engine decide which friction factor applies over an interval?', '["By the deeper of the two sections.", "By the section that contains the interval''s midpoint.", "By length-weighting the two factors where an interval straddles a section boundary, which resolves the shoe exactly.", "By the section containing the interval''s upper end, which is the direction the recursion is marching."]'::jsonb, 1, 'At a 10 m step that leaves a discretisation of up to 10 m at the shoe, which is one of the reasons the step matters.'),
  ('torquedrag', 'intermediate', 'module', 'm01-the-friction-factor', 9, 'On the build-and-hold well, what is the pick-up hookload''s response to the open-hole factor?', '["Quadratic, because of the feedback.", "Piecewise, with a break at the factor where the string first enters compression somewhere along its length.", "Exponential, because friction adds tension which adds side force which adds friction in a compounding loop.", "Exactly linear, to twelve significant figures across the range 0.15 to 0.50."]'::jsonb, 3, 'The feedback is real and weak on this geometry, so the differences between successive sweep points are constant.'),
  ('torquedrag', 'intermediate', 'module', 'm01-the-friction-factor', 10, 'Why is the slack-off response NOT linear on the same well?', '["Because the friction factor is applied differently.", "Because the direction cosines change sign when the string moves downward, which introduces a discontinuity.", "Because slack off puts the string into less tension and eventually into compression, where the behaviour changes.", "Because the weight on bit is applied while tripping in, which adds a nonlinear boundary condition at the bit."]'::jsonb, 2, 'That asymmetry means a calibration done on pick up is more stable than one done on slack off.'),
  ('torquedrag', 'intermediate', 'module', 'm01-the-friction-factor', 11, 'What does a cuttings bed do to a fitted friction factor?', '["Raises it, even though ploughing through a bed is not proportional to normal force at all.", "Lowers it, by lubricating the contact.", "Leaves it unchanged, since the model computes the side force from the geometry rather than from the hole''s contents.", "Makes it depth-dependent in a way the model detects, since the fit will not converge on a single value."]'::jsonb, 0, 'It presents as a factor that rises with penetration rate and falls when you circulate, which is not how a coefficient of friction behaves.'),
  ('torquedrag', 'intermediate', 'module', 'm01-the-friction-factor', 12, 'How does differential sticking present in a fitted factor?', '["It appears suddenly at one depth.", "It rises the longer the string is stationary and drops when the string is worked.", "It rises with rotary speed, because a rotating string breaks the filter cake seal and reduces the clamping force.", "It falls with depth, because the pressure differential is largest at the shallowest permeable formation."]'::jsonb, 1, 'The depth-specific behaviour is a ledge or a keyseat, and distinguishing the two is why the calibration has to be done repeatedly.'),
  ('torquedrag', 'intermediate', 'module', 'm01-the-friction-factor', 13, 'What distinguishes a stiff-assembly effect from a hole-condition effect?', '["It only appears in cased hole.", "It rises with rate of penetration, because a faster bit produces more cuttings for the assembly to plough through.", "It is symmetric between pick up and slack off, whereas a hole-condition effect acts in one direction only.", "It follows the assembly''s position rather than a fixed depth in the hole."]'::jsonb, 3, 'The soft-string model spread the contact smoothly and a stiff assembly concentrates it, so the effect moves with the assembly.'),
  ('torquedrag', 'intermediate', 'module', 'm01-the-friction-factor', 14, 'How many newtons does 0.001 of factor move that well''s pick-up reading?', '["About 8 N per 0.001 of factor.", "It cannot be stated as a single number, because the response curves upward at the higher end of the range.", "About 785 N per 0.001 of factor, constant across the range.", "About 78 kN per 0.001 of factor, which is why a small error in the factor changes the rig specification."]'::jsonb, 2, 'Constant because the response is linear on this well. On a longer, more deviated well the same table curves upward.'),
  ('torquedrag', 'intermediate', 'module', 'm01-the-friction-factor', 15, 'A perfectly straight sweep line looks reassuring. What does it not establish?', '["Accuracy, since a linear response to a parameter absorbing four effects is still absorbing them.", "A single-point calibration.", "A quotable sensitivity, since a nonlinear response would need the sensitivity stated at a particular factor.", "A guarantee that the bisection converges, which needs monotonicity rather than linearity to be assured."]'::jsonb, 0, 'The bisection needs monotonicity, which linearity implies. Accuracy is a separate question that the fit cannot answer.'),
  ('torquedrag', 'intermediate', 'module', 'm02-torque', 1, 'When a tool joint slides both axially and tangentially, which way does friction point?', '["Opposite to the axial motion only.", "Opposite to the tangential motion only, since at 120 rpm the surface speed dominates the axial trip speed.", "Opposite to the vector sum of the two velocities.", "Perpendicular to the wall, which is the direction the normal force acts and therefore the direction friction resists."]'::jsonb, 2, 'The friction magnitude is mu N in total, and the two direction cosines split it according to how the joint is moving.'),
  ('torquedrag', 'intermediate', 'module', 'm02-torque', 2, 'What is the sum of the squares of the two direction cosines?', '["Exactly one, so the total friction is conserved.", "Exactly two, one per direction.", "It depends on the ratio of the velocities, and it approaches one only when one of the two dominates the other.", "Zero, because the two components act in perpendicular directions and therefore cancel in the sum."]'::jsonb, 0, 'Rotating does not reduce friction; it moves it. The top drive pays for what the drawworks was paying for.'),
  ('torquedrag', 'intermediate', 'module', 'm02-torque', 3, 'At 120 rpm on this tool joint, what is the tangential surface speed?', '["About 0.3 m/s, the same as the trip speed.", "About 1.057 m/s, which is three and a half times the 0.3 m/s trip speed.", "About 10.6 m/s, which is why almost all of the friction goes into the tangential direction while back reaming.", "It depends on the hole diameter, since the joint rolls around the inside of the hole rather than spinning in place."]'::jsonb, 1, 'Two pi times 0.0841375 m times 120 over 60. That ratio is why the sharing while back reaming is so lopsided.'),
  ('torquedrag', 'intermediate', 'module', 'm02-torque', 4, 'At what rotary speed do the two direction cosines become equal, at a 0.3 m/s trip speed?', '["At 120 rpm, the standard value.", "At 60 rpm, which is half the standard and therefore halves the tangential velocity to match the trip speed.", "They are never equal, because the tangential term always exceeds the axial one for any positive rotary speed.", "Around 34 rpm, where the surface speed equals the trip speed."]'::jsonb, 3, 'Below that the axial share dominates. It is why very slow rotation does much less for weight transfer than moderate rotation.'),
  ('torquedrag', 'intermediate', 'module', 'm02-torque', 5, 'Which radius carries the torque?', '["The pipe body radius.", "The mean of the tool joint and body radii, weighted by the fraction of each joint''s length that each represents.", "The tool joint radius, because that is the surface touching the wall.", "The hole radius, since the friction acts at the wall rather than at the pipe''s outer surface."]'::jsonb, 2, 'For this drill pipe the tool joint radius is 1.325 times the body radius, so the choice moves the torque by a quarter.'),
  ('torquedrag', 'intermediate', 'module', 'm02-torque', 6, 'What does a missing tool joint diameter do to the calculation?', '["Understates the torque by about 24.5 percent and leaves the hookload almost unchanged.", "Prevents the calculation from running.", "Understates both the torque and the hookload by the same proportion, since both depend on the contact radius.", "Overstates the torque, because the engine falls back to the hole radius rather than the pipe body radius."]'::jsonb, 0, 'That asymmetry is exactly the size of error that gets mistaken for a friction factor problem and then compensated in the wrong place.'),
  ('torquedrag', 'intermediate', 'module', 'm02-torque', 7, 'Where does the contact radius enter the calculation?', '["Only in the moment arm.", "In the moment arm and in the tangential velocity, so it affects both the torque and the direction cosines.", "Only in the tangential velocity, since the moment arm in the torque recursion is the hole radius rather than the pipe''s.", "In the buckling limits, through the radial clearance, and nowhere else in the torque and drag calculation."]'::jsonb, 1, 'The two effects are in the same direction for torque and in opposite directions for hookload, which is why the hookload barely moves.'),
  ('torquedrag', 'intermediate', 'module', 'm02-torque', 8, 'Why is the torque profile flat in a vertical hole?', '["Because the torque is measured at surface.", "Because the weight term in the torque recursion is proportional to the cosine of the inclination, which is one.", "Because the tangential direction cosine is zero in a vertical hole, since there is no low side to slide against.", "There is no side force, so no friction torque accumulates over any interval."]'::jsonb, 3, 'The torque recursion has no weight term at all. Weight adds to torque only through the side force it produces.'),
  ('torquedrag', 'intermediate', 'module', 'm02-torque', 9, 'What fraction of a deviated well''s surface torque is friction rather than bit torque?', '["About half.", "It varies from zero to a hundred percent depending on the rate of penetration, which sets the bit torque.", "Around 83 to 90 percent on the wells in this course.", "About a quarter, since the bit is where the rock is being cut and that is where most of the work is done."]'::jsonb, 2, 'That high share is why torque is a better hole-condition indicator than hookload, and it comes through a noisier instrument.'),
  ('torquedrag', 'intermediate', 'module', 'm02-torque', 10, 'Why does going on bottom not raise the torque by exactly the bit torque?', '["Because the compression it adds changes the side force distribution near the bit at the same time.", "Because the bit torque is only partly transmitted.", "Because the weight on bit reduces the tension at surface, which reduces the friction over the whole string.", "Because the rotary speed drops when weight is applied, which changes the tangential direction cosine."]'::jsonb, 0, 'On the build-and-hold well the net difference is a few hundred newton-metres against a bit torque of 2700.'),
  ('torquedrag', 'intermediate', 'module', 'm02-torque', 11, 'In which geometry does applying weight at the bit INCREASE the friction above it?', '["The vertical one.", "The horizontal one, where the compression increases rather than decreases the side force.", "The slant one, because a constant tangent has a uniform side force that scales directly with the axial load.", "The build-and-hold one, because the compression acts through the build section where the curvature is largest."]'::jsonb, 1, 'In a horizontal section the side force is dominated by the weight term, and a buckling string presses outward rather than lying on the low side.'),
  ('torquedrag', 'intermediate', 'module', 'm02-torque', 12, 'Which torque reading is the right one to calibrate a friction factor against?', '["The on-bottom one, being larger.", "The average of the two, since the difference between them contains information about the compression near the bit.", "The sliding one, because it isolates the bit torque exactly and the friction can then be obtained by subtraction.", "The off-bottom one, because it contains no bit torque at all."]'::jsonb, 3, 'An on-bottom torque contains a bit torque that depends on the bit, the formation, the weight and the rate of penetration, none of which the model knows.'),
  ('torquedrag', 'intermediate', 'module', 'm02-torque', 13, 'What does back reaming do to the torque relative to rotating off bottom?', '["Roughly doubles it.", "Lowers it, because some of the friction that was going into torque is now going into the axial direction instead.", "Raises it slightly, because the tangential share was already near one and barely changes.", "Leaves it unchanged, since the total friction is conserved and the tangential share is fixed by the rotary speed."]'::jsonb, 2, 'Meanwhile the axial cosine goes from zero to about 0.27, which is why the hookload moves a great deal and the torque hardly does.'),
  ('torquedrag', 'intermediate', 'module', 'm02-torque', 14, 'What would a section where torque FALLS going up indicate?', '["An input error, since friction always opposes rotation and torque only accumulates.", "A downhole motor.", "A section where the string is in compression, which reverses the sign of the tangential friction contribution.", "A change in string composition to a smaller tool joint, which reduces the moment arm and therefore the torque."]'::jsonb, 0, 'A smaller tool joint reduces the RATE of accumulation and cannot make it negative. Anything else is a defect in the setup.'),
  ('torquedrag', 'intermediate', 'module', 'm02-torque', 15, 'What is the practical way to separate bit torque from friction torque on a rig?', '["Subtract the modelled bit torque.", "Compare an off-bottom reading with an on-bottom reading at the same depth minutes apart.", "Measure the torque with a downhole tool near the bit, which is the only method that separates the two directly.", "Run the model at two friction factors and take the difference, which isolates the friction contribution."]'::jsonb, 1, 'A downhole measurement is genuinely better where it exists. The pick-up-and-read comparison is what a driller can do on every connection.'),
  ('torquedrag', 'intermediate', 'module', 'm03-side-force', 1, 'Why is the maximum side force larger tripping out than tripping in on the same well?', '["Because the trip speed is higher.", "Friction adds to tension going up, and more tension means more side force in every curve.", "Because the weight on bit is released while tripping out, which allows the string to straighten and press harder.", "Because the friction factor is higher going up, which is the standard convention for a pick-up calculation."]'::jsonb, 1, 'It is a positive feedback with a gain below one, so it converges rather than running away, and it is why the model integrates rather than evaluates.'),
  ('torquedrag', 'intermediate', 'module', 'm03-side-force', 2, 'Where in a build-and-hold well does the side force peak?', '["At total depth.", "In the hold section, where the string lies against the low side over the longest continuous interval of the well.", "Near the top of the build, where curvature is present and the tension is highest.", "At the kick-off, where the well first departs from vertical and the curvature is introduced abruptly."]'::jsonb, 2, 'Below the build the curvature is gone and above it both terms are zero, so the profile is a hump rather than a ramp.'),
  ('torquedrag', 'intermediate', 'module', 'm03-side-force', 3, 'In a horizontal lateral rotating on bottom, what does the maximum side force per metre equal?', '["The buoyed weight per metre of whatever component is there.", "The tension times the local curvature.", "The buoyed weight per metre times the friction factor, since friction is what holds the string against the wall.", "Twice the buoyed weight per metre, because the string presses on the low side and is pushed back by the reaction."]'::jsonb, 0, 'No curvature, and the sine of ninety degrees is one. If a side force in a horizontal section is not the local buoyed weight, the hole is not straight there.'),
  ('torquedrag', 'intermediate', 'module', 'm03-side-force', 4, 'What is a dogleg severity of 3 degrees per 30 m, in radians per metre?', '["About 0.1, one tenth of a radian.", "About 3, since the severity is already an angular rate and only the length normalisation needs converting.", "It cannot be converted without the inclination, which scales the azimuth part of the dogleg.", "About 0.001745, so each newton of tension gives that many newtons per metre of side force."]'::jsonb, 3, 'At 400 kN of tension that is about 698 N per metre, which is the right order for the build-and-hold well''s hump.'),
  ('torquedrag', 'intermediate', 'module', 'm03-side-force', 5, 'Why is a deep kick-off with a hard build expensive in torque and drag?', '["Because a deep build takes longer to drill.", "Because the dogleg severity has to be higher to reach the same target from a deeper starting point.", "Because the whole string above it pulls through the curvature, so the tension there is large.", "Because the friction factor is higher deeper in the hole, where the formation is harder and the cake thinner."]'::jsonb, 2, 'The severity does have to be higher, which compounds the effect. The tension is the larger of the two contributions.'),
  ('torquedrag', 'intermediate', 'module', 'm03-side-force', 6, 'Why does drag grow faster than linearly with measured depth on a deviated well?', '["More depth gives more tension, which gives more side force, which gives more friction, which adds tension.", "Because the friction factor rises with depth.", "Because the buoyancy factor falls with depth as the mud density rises under compression and temperature.", "Because the hole gets smaller with depth, which reduces the clearance and increases the contact pressure."]'::jsonb, 0, 'That compounding is why extended reach drilling has a limit rather than just being expensive.'),
  ('torquedrag', 'intermediate', 'module', 'm03-side-force', 7, 'What contributes no curvature side force at all?', '["A vertical section under high tension.", "A straight tangent, whatever its inclination.", "A horizontal lateral, since a lateral has no vertical component of weight and therefore no contact force.", "A build section drilled at a constant rate, since a constant curvature produces a constant and therefore cancelling force."]'::jsonb, 1, 'A vertical section also contributes none, and so does a tangent. The tangent still has the weight term, which the vertical section does not.'),
  ('torquedrag', 'intermediate', 'module', 'm03-side-force', 8, 'What is the standard extended reach design prescription, in side-force terms?', '["Build late and build hard.", "Kick off as deep as the formation allows, so that the vertical section carries as much of the depth as possible.", "Use the highest hold angle the hole cleaning allows, since a steeper hold reduces the measured depth to target.", "Build early, build gently, hold long."]'::jsonb, 3, 'A gentle build minimises the curvature term where tension is high, and an early build puts what curvature there is where tension is low.'),
  ('torquedrag', 'intermediate', 'module', 'm03-side-force', 9, 'What usually caps the hold angle in practice, rather than the drag calculation?', '["The survey tool''s inclination limit.", "The casing running calculation, which becomes the binding constraint above about 60 degrees of hold angle.", "Hole cleaning, because cuttings beds form above about 30 degrees.", "The buckling limits, which fall with inclination and make a steep hold more likely to buckle the string."]'::jsonb, 2, 'The buckling limits RISE with inclination, so a steep hold is harder to buckle in, not easier.'),
  ('torquedrag', 'intermediate', 'module', 'm03-side-force', 10, 'What scales the azimuth part of the side force?', '["The cosine of the inclination.", "The sine of the inclination.", "The ratio of the azimuth change to the inclination change, which sets the plane the dogleg lies in.", "Nothing: azimuth change and inclination change enter the expression with equal weight at every attitude."]'::jsonb, 1, 'That is the same factor as in the dogleg severity formula, and for the same reason: turning at low inclination barely bends the string.'),
  ('torquedrag', 'intermediate', 'module', 'm03-side-force', 11, 'At 5 degrees of inclination, what fraction of an azimuth change becomes curvature?', '["About 0.087, so a 10 degree turn is worth less than a 1 degree build.", "The whole of it.", "About half, since at low inclination the horizontal and vertical components of the change are comparable.", "None at all, because azimuth is undefined near vertical and the term is excluded below a threshold inclination."]'::jsonb, 0, 'At 90 degrees the same turn is worth the full 10 degrees, which is why azimuth is set while the well is still shallow.'),
  ('torquedrag', 'intermediate', 'module', 'm03-side-force', 12, 'Why is the azimuth term inside a hypotenuse with the inclination term rather than added to it?', '["Because the sum could otherwise be negative.", "Because the azimuth term is scaled by the sine of inclination, and adding a scaled term to an unscaled one is inconsistent.", "Because the two curvatures are perpendicular, so they combine in quadrature.", "Because the hypotenuse form is a convention from the dogleg severity formula, carried over for consistency."]'::jsonb, 2, 'Building bends the string in the vertical plane and turning bends it horizontally. A well doing both has less total curvature than the sum.'),
  ('torquedrag', 'intermediate', 'module', 'm03-side-force', 13, 'What follows from the perpendicularity of the two curvature contributions?', '["The two effects cancel exactly.", "The azimuth term can be ignored below about 30 degrees of inclination, where its contribution is under a tenth.", "The total dogleg is always the larger of the two, since the smaller contributes nothing to the hypotenuse.", "A three-dimensional turn is cheaper than doing the build and the turn in sequence."]'::jsonb, 3, 'Doing them in sequence produces two curvatures in series; doing them together produces one whose magnitude is the quadrature sum.'),
  ('torquedrag', 'intermediate', 'module', 'm03-side-force', 14, 'Why compare wells by side force per metre rather than by total drag?', '["Because the total is hard to compute.", "Because the total is dominated by length and the per-metre value is the local geometry.", "Because the per-metre value is what the friction factor multiplies, and the total is what the derrick sees.", "Because side force per metre is the same on every well with the same string, so it is a useful control."]'::jsonb, 1, 'The three-dimensional well has a lower total than the build-and-hold well despite a comparable maximum inclination, entirely because it is shorter.'),
  ('torquedrag', 'intermediate', 'module', 'm03-side-force', 15, 'What does the largest side force in the fixture set actually represent?', '["A buckled string pressing outward, which is a flag rather than a force.", "The worst case in a build section.", "The collars in a horizontal lateral, which have the largest buoyed weight per metre of any component in the string.", "The peak of the curvature term on the build-and-hold well while tripping out, which is the highest tension case."]'::jsonb, 0, 'It appears on the horizontal well sliding, where the model is computing side force from a compression the string could not have carried.'),
  ('torquedrag', 'intermediate', 'module', 'm04-calibration', 1, 'What is calibration, in torque and drag?', '["The inverse problem: given an observed hookload, find the friction factor that reproduces it.", "A laboratory measurement of friction.", "A comparison of the modelled hookload against the measured one, expressed as a percentage difference at each depth.", "The process of adjusting the survey and the string description until the model matches the rig''s readings."]'::jsonb, 0, 'It is the only way the friction factor ever gets a value on a specific well.'),
  ('torquedrag', 'intermediate', 'module', 'm04-calibration', 2, 'How does the engine solve for the friction factor?', '["A closed-form inversion.", "Newton iteration on a finite-difference derivative, which converges quadratically and needs a step choice.", "Bisection, 200 halvings over a monotone response.", "A least-squares fit over every hookload reading recorded during the trip, weighted by the depth of each."]'::jsonb, 2, 'Two hundred halvings takes the bracket far below machine precision, so the answer is deterministic and reproducible to the last bit.'),
  ('torquedrag', 'intermediate', 'module', 'm04-calibration', 3, 'Why bisection rather than something faster?', '["Because the response is discontinuous.", "The forward run is cheap and the response is monotone, so it needs no derivative and cannot diverge.", "Because the bracket is known in advance, which is the condition bisection requires and Newton''s method does not.", "Because bisection is the only method that converges on a linear response, where a derivative method would divide by zero."]'::jsonb, 1, 'Two hundred forward runs on a hundred-station well is milliseconds. A derivative method would introduce a step choice for nothing.'),
  ('torquedrag', 'intermediate', 'module', 'm04-calibration', 4, 'Which observation is the right one to fit against?', '["The rotating-off-bottom hookload.", "The slack-off hookload, because it is the smallest of the three and therefore the most sensitive to the factor.", "The average of the three, which smooths out the measurement noise in any individual reading.", "The pick-up hookload, because its response is linear and friction contributes most to it."]'::jsonb, 3, 'Rotating off bottom does not depend on the friction factor at all, and slack off goes nonlinear once compression starts.'),
  ('torquedrag', 'intermediate', 'module', 'm04-calibration', 5, 'What is dangerous about the calibration always succeeding?', '["The number it returns carries no information about whether the model was right.", "It can converge to the wrong root.", "It takes a long time on a well with many stations, so the calibration is often skipped in practice.", "It requires an observation that is often not recorded, so the fit is usually done on an assumed value."]'::jsonb, 0, 'A missing survey section, a blank tool joint column and a wrong mud weight all produce a fit that reproduces the hookload exactly and is wrong.'),
  ('torquedrag', 'intermediate', 'module', 'm04-calibration', 6, 'A wrong mud weight of 1500 is entered as 1440. Which way does the fitted factor move?', '["Up, to compensate for the extra weight.", "Down, because the modelled hookload was too high and the fit compensates.", "It does not move, because buoyancy scales the weight and the friction proportionally so the ratio is preserved.", "It depends on the operation, since buoyancy affects pick up and slack off in opposite directions."]'::jsonb, 1, 'A lighter mud means a heavier string in the hole, so the model predicts more hookload than it should, and less friction is needed to reach the target.'),
  ('torquedrag', 'intermediate', 'module', 'm04-calibration', 7, 'What is the test that catches what a fit hides?', '["Repeat the fit at a finer step.", "Fit at two different target values and confirm the two answers bracket the book value for that hole condition.", "Fit on one observation and predict another.", "Compare the fitted factor against the published range for the mud type, and reject it if it falls outside."]'::jsonb, 2, 'If the model is right both match. If the factor absorbed something that is not friction, they will not, because that thing does not act symmetrically.'),
  ('torquedrag', 'intermediate', 'module', 'm04-calibration', 8, 'Which cross-check has the most power?', '["Fit on pick up and predict slack off.", "Fit at one depth and predict the same observation at a deeper one, which tests the depth dependence of the factor.", "Fit with the engine and compare against a second implementation of the same model on the same inputs.", "Fit on hookload and predict torque."]'::jsonb, 3, 'The two depend on the factor through different paths: torque weights by the contact radius and hookload does not.'),
  ('torquedrag', 'intermediate', 'module', 'm04-calibration', 9, 'Which error does a hookload fit NOT catch when it predicts torque?', '["A wrong mud weight, because it scales both similarly.", "A missing tool joint diameter.", "A cuttings bed, which produces axial ploughing force but relatively less rotational resistance.", "A missing stabiliser, which is a local contact with a large radius that the string description does not have."]'::jsonb, 0, 'A survey error that scales the whole side force is also missed, so the test is a filter rather than a proof.'),
  ('torquedrag', 'intermediate', 'module', 'm04-calibration', 10, 'How would a dirty hole present in a hookload fit and a torque prediction?', '["Both high by the same fraction.", "Hookload high, torque normal, because ploughing is axial and not proportional to normal force.", "Torque high and hookload normal, because cuttings are dragged around the annulus by the rotating string.", "Neither affected, since cuttings are in the annulus rather than between the string and the wall."]'::jsonb, 1, 'That is a real and useful signal, and it points at hole cleaning rather than at geometry.'),
  ('torquedrag', 'intermediate', 'module', 'm04-calibration', 11, 'How many friction factors are there, and how many observations usually?', '["One of each, so the fit is exact.", "Two of each, since a pick-up and a slack-off reading are recorded at every connection along with the rotating value.", "At least two, and usually one, so the fit is under-determined.", "One factor and several observations, so the fit is over-determined and a least-squares solution is used."]'::jsonb, 2, 'One equation and two unknowns. No amount of bisection fixes that; something has to be held fixed.'),
  ('torquedrag', 'intermediate', 'module', 'm04-calibration', 12, 'What is the standard way of handling the under-determination?', '["Fit both and take the average.", "Assume the two are equal, which removes one unknown and makes the fit exact with a single observation.", "Use the ratio of the two published typical values as a constraint, which fixes one in terms of the other.", "Take a book value for the cased factor and fit the open-hole one."]'::jsonb, 3, 'It is defensible when most of the side force is in open hole, and indefensible when the shoe sits deep inside a build.'),
  ('torquedrag', 'intermediate', 'module', 'm04-calibration', 13, 'What is the better way, when the data allow it?', '["Fit at two depths, one before the shoe is drilled out and one after several hundred metres of open hole.", "Fit at a single depth twice.", "Fit the open-hole factor and then adjust the cased one until the torque prediction matches the measured value.", "Use a commercial least-squares package, which solves for both factors from a single hookload observation."]'::jsonb, 0, 'Two observations and two unknowns, both hookloads on the same string, and it requires only that somebody recorded the first reading.'),
  ('torquedrag', 'intermediate', 'module', 'm04-calibration', 14, 'What sensitivity test tells you how much the under-determination cost?', '["Refine the integration step.", "Refit the open-hole factor at several assumed cased values and see how much it moves.", "Compare the fitted value against the book value, since a large gap indicates that something else has been absorbed.", "Fit at two different target hookloads and confirm the two fitted values are consistent with a linear response."]'::jsonb, 1, 'If the fitted value barely moves, the cased section is not contributing much and the assumption is harmless. If it moves a lot, the fit is poorly conditioned.'),
  ('torquedrag', 'intermediate', 'module', 'm04-calibration', 15, 'What is the failure mode in reporting a fitted friction factor?', '["Quoting too many decimal places.", "Quoting it without the hookload it was fitted to, which is the observation somebody else would need to reproduce it.", "Quoting one number without saying which section it applies to and what the other was assumed to be.", "Quoting it without the date, since hole condition changes over hours and a factor goes out of date quickly."]'::jsonb, 2, 'The hookload and the date both matter and are secondary. A number that does not say what it applies to cannot be used by anyone else at all.'),
  ('torquedrag', 'intermediate', 'module', 'm05-against-the-oracle', 1, 'What is in the goldens file?', '["A published textbook example.", "Five wells with their inputs, and expected summaries and checkpoints for four or five operations each.", "The engine''s own output, recorded once and stored so that later changes can be detected as regressions.", "A set of field measurements from real wells, against which the model''s predictions have been validated."]'::jsonb, 1, 'More than a hundred published values in all, and they came from a separate program rather than from this one.'),
  ('torquedrag', 'intermediate', 'module', 'm05-against-the-oracle', 2, 'How were the goldens generated?', '["By the engine itself, on an earlier version.", "By analytical integration of the soft-string equations, which have a closed form on a piecewise-constant survey.", "By an independent Runge-Kutta integration of the same equations, in a different language.", "By digitising the figures from the original Johancsik and Sheppard paper on soft-string torque and drag."]'::jsonb, 2, 'Different language, different integration order, different author. The value of the check is proportional to how independent it is.'),
  ('torquedrag', 'intermediate', 'module', 'm05-against-the-oracle', 3, 'Why an independent implementation rather than a hand check?', '["Because the soft-string model has no closed-form solution on a real survey.", "Because hand checks are slow.", "Because the equations are too long to work by hand, though a closed form exists for a piecewise-linear survey.", "Because the goldens have to cover five wells and six operations, which is too many cases to check individually."]'::jsonb, 0, 'There is no textbook example with a printed answer to four decimals, the way there is for minimum curvature.'),
  ('torquedrag', 'intermediate', 'module', 'm05-against-the-oracle', 4, 'What does agreement between the two implementations prove?', '["That the model describes a drill string.", "That the soft-string assumption is adequate, since two independent derivations of it agree on the same answers.", "That the friction factor is correct, since a wrong factor would produce a disagreement between the two.", "That two people reading the same equations wrote code producing the same numbers."]'::jsonb, 3, 'Both share the soft-string assumption, the Coulomb friction model and the omission of dynamics. Agreeing says nothing about any of that.'),
  ('torquedrag', 'intermediate', 'module', 'm05-against-the-oracle', 5, 'What does DISAGREEMENT prove?', '["That the goldens are out of date.", "That the two implementations are using different inputs, since the same equations on the same inputs must agree.", "That at least one of them is wrong, which turns a vague worry into a number that can be chased.", "That the disagreement is discretisation, since both are integrating the same continuous equations numerically."]'::jsonb, 2, 'Whether it is discretisation or a model difference is exactly what refining the step is for.'),
  ('torquedrag', 'intermediate', 'module', 'm05-against-the-oracle', 6, 'Where are the two worst disagreements?', '["On the vertical well, where the oracle errs.", "Both on the horizontal well, on operations that put the string into compression.", "On the build-and-hold well, where the build section produces the largest curvature and therefore the largest side force.", "Spread evenly across all five wells, at a relative level of about 1e-4 everywhere with no case standing out."]'::jsonb, 1, 'Everywhere else the agreement is at or below the 1e-4 the goldens'' own description asks for.'),
  ('torquedrag', 'intermediate', 'module', 'm05-against-the-oracle', 7, 'Why does the relative measure mislead on the trip-in case?', '["Because the hookload is small compared with the forces inside the string, so the denominator is tiny.", "Because relative errors are always misleading.", "Because the hookload is negative, and a relative measure on a negative number changes sign with the convention used.", "Because the oracle reports a hookload with fewer significant figures than the engine, which inflates the ratio."]'::jsonb, 0, 'The same absolute gap on the pick-up hookload is two parts in a thousand rather than seven percent.'),
  ('torquedrag', 'intermediate', 'module', 'm05-against-the-oracle', 8, 'Why does the absolute measure also mislead there?', '["Because newtons are the wrong units.", "Because the absolute gap grows with the length of the well, so it is not comparable between the five cases.", "Because both implementations are computing the same thing wrongly, so their agreement would be misleading too.", "Because the case has already been flagged as buckled from end to end."]'::jsonb, 3, 'Both are computing friction from a compression a real drill string could not carry. They disagree about a number that does not describe anything.'),
  ('torquedrag', 'intermediate', 'module', 'm05-against-the-oracle', 9, 'What does refining the step do to the horizontal well''s gap?', '["Leaves it unchanged.", "Doubles it, because a finer grid resolves more of the curvature and therefore more of the friction.", "Halves it with each halving of the step, converging toward zero.", "Reduces it to a floor of about a hundred newtons, below which the two implementations differ structurally."]'::jsonb, 2, 'First-order convergence toward zero means it is discretisation and the two implementations are computing the same thing.'),
  ('torquedrag', 'intermediate', 'module', 'm05-against-the-oracle', 10, 'Halve the step six times on a slant well rotating on bottom. What happens?', '["Halves it, as on the horizontal well.", "Nothing: it settles at a few tens of newtons and stays there.", "Increases it, because the finer grid resolves the section boundary at the shoe more precisely than the oracle does.", "Reduces it to zero, but more slowly, because the slant well has fewer stations to integrate over."]'::jsonb, 1, 'That is a model difference rather than discretisation, and no amount of refinement will close it.'),
  ('torquedrag', 'intermediate', 'module', 'm05-against-the-oracle', 11, 'Which implementation is closer, and what settles it?', '["The engine, and the vertical well''s closed-form answer settles it.", "The oracle, being fourth-order.", "Neither can be preferred, since both are converging and no third source is available on a real survey.", "The engine, because it uses a midpoint predictor which is unconditionally stable on a stiff problem."]'::jsonb, 0, 'The engine reproduces the buoyed string weight to about four nanonewtons and the oracle is more than forty newtons away from it.'),
  ('torquedrag', 'intermediate', 'module', 'm05-against-the-oracle', 12, 'What does the vertical case NOT settle?', '["Whether the buoyancy factor is right.", "Whether the string composition lookup is right, since a vertical well uses only drill pipe over most of its length.", "Whether the integration grid is right, since with no friction the recursion has nothing to accumulate.", "Whether the engine is right on the friction, curvature and direction-cosine terms."]'::jsonb, 3, 'It exercises the weight integral, the buoyancy factor, the component lookup and the grid, and touches nothing else.'),
  ('torquedrag', 'intermediate', 'module', 'm05-against-the-oracle', 13, 'What is the honest form of the disagreement statement?', '["The relative measure alone.", "The absolute measure alone, since a relative measure on a near-zero denominator is meaningless by construction.", "Both measures, plus where it occurs and what the refinement study showed.", "The claim that the two agree to 1e-4, with the exceptions noted in a footnote for completeness."]'::jsonb, 2, 'Neither number alone would be honest. Quoting only one of them can be made to say almost anything.'),
  ('torquedrag', 'intermediate', 'module', 'm05-against-the-oracle', 14, 'What is the general lesson when two implementations disagree with no closed form available?', '["Take the average of the two.", "Look for a degenerate case that does have one: zero friction, zero rate, infinite time.", "Refine both until they converge, since two convergent schemes on the same equations must reach the same limit.", "Prefer the higher-order scheme, since its truncation error falls faster with the step and its limit is more reliable."]'::jsonb, 1, 'It will not settle everything, and it settles more than any comparison between the two implementations can.'),
  ('torquedrag', 'intermediate', 'module', 'm05-against-the-oracle', 15, 'What is the practical rule the step study gives?', '["Refine once on anything you will rely on and check the answer moved by less than you care about.", "Always use the finest step.", "Use 10 m for planning and 1 m for anything that will go into a rig contract or a permit application.", "Refine until the answer matches the oracle, which is the reference the engine is checked against."]'::jsonb, 0, 'That is one extra run, and it is the difference between a number you have checked and a number you have not.'),
  ('torquedrag', 'intermediate', 'module', 'm06-the-professional-reading', 1, 'Having finished the Professional modules, which skill have you earned?', '["Computing a hookload for six operations.", "Saying what a friction factor absorbed and what a fitted one predicts for an observation you did not fit.", "Judging whether the pipe will buckle and what the resulting side force does to the casing it turns against.", "Designing a trajectory whose torque and drag stay within a stated rig''s hookload and top drive ratings."]'::jsonb, 1, 'The first is the Associate tier and the second is the Expert tier. Design is the application rather than the certified skill.'),
  ('torquedrag', 'intermediate', 'module', 'm06-the-professional-reading', 2, 'What is the one number in the model that nobody measured?', '["The friction factor.", "The buoyancy factor.", "The tool joint radius, which is taken from the string description and is often left blank in practice.", "The integration step, which is a numerical choice rather than a physical quantity and defaults to 10 m."]'::jsonb, 0, 'The step is a numerical choice and its effect can be measured by refining. The friction factor cannot be checked that way at all.'),
  ('torquedrag', 'intermediate', 'module', 'm06-the-professional-reading', 3, 'What single difference produces every distinction between the six operations?', '["The friction factor in each section.", "The boundary condition at the bit, which is the only thing that changes between a tripping and an on-bottom run.", "The pair of direction cosines set by the ratio of trip speed to tool joint surface speed.", "The rotary speed, which enters the tangential velocity and therefore scales the whole friction force."]'::jsonb, 2, 'The bit boundary conditions add the weight on bit and the bit torque on top, and the cosines do everything else.'),
  ('torquedrag', 'intermediate', 'module', 'm06-the-professional-reading', 4, 'What is the tool joint radius over the pipe body radius on this drill pipe?', '["1.0, they are the same.", "About 2, since a tool joint is roughly twice the diameter of the pipe body it is welded onto.", "It varies by joint, so no single ratio applies and the torque must be integrated per component.", "1.325, so using the body radius understates the torque by about a quarter."]'::jsonb, 3, 'That is exactly the size of error that gets mistaken for a friction factor problem and compensated in the wrong place.'),
  ('torquedrag', 'intermediate', 'module', 'm06-the-professional-reading', 5, 'Where is side force largest, and where do people expect it?', '["At total depth, as people expect.", "Near the top of a build; people expect total depth.", "In the hold section, whereas people expect the build, because the hold has the longest continuous contact length.", "At the casing shoe, whereas people expect the kick-off, because the friction factor steps there."]'::jsonb, 1, 'At total depth the tension is small because there is very little string below to pull on.'),
  ('torquedrag', 'intermediate', 'module', 'm06-the-professional-reading', 6, 'What makes a calibration dangerous rather than merely useful?', '["It is slow to run.", "It converges to a local rather than a global minimum, so different starting brackets give different answers.", "It always succeeds, so the number it returns says nothing about whether the model was right.", "It requires an observation that is rarely recorded accurately, so the fitted value carries the measurement error."]'::jsonb, 2, 'A survey gap, a blank tool joint column and a wrong mud weight all produce fits that reproduce the hookload exactly.'),
  ('torquedrag', 'intermediate', 'module', 'm06-the-professional-reading', 7, 'One fitted number and one observation is circular. What removes the circularity?', '["Report what the fitted factor predicts for the observation you did not fit to.", "Report the fitted value to more decimals.", "Report the range of factors that reproduce the observation within the measurement uncertainty of the hookload.", "Report the book value alongside the fitted one, so the reader can see how far the fit moved from the prior."]'::jsonb, 0, 'One number and one observation is a tautology. One number and two observations is a test.'),
  ('torquedrag', 'intermediate', 'module', 'm06-the-professional-reading', 8, 'What does the goldens comparison establish, and what does it not?', '["That the model has been validated in the field.", "That the engine''s discretisation is adequate at the default step, which is the claim the goldens'' tolerance makes.", "That the friction factors used in the fixture set are representative of real wells drilled in similar conditions.", "That two independent codes agree; not that the model describes a drill string."]'::jsonb, 3, 'Both share the soft-string assumption, the Coulomb model and the omission of dynamics, so agreeing says nothing about any of it.'),
  ('torquedrag', 'intermediate', 'module', 'm06-the-professional-reading', 9, 'What does the capstone ask you for?', '["Six hookloads from five wells.", "Two torques, a side force, a back-reaming torque, a minimum tension and a fitted friction factor.", "The buckling limits, the two utilizations and the casing wear a rotating schedule produces from the side forces.", "The buoyancy factor and five hookloads, at a mud weight the lessons in this tier did not use."]'::jsonb, 1, 'The first of the wrong answers is the Expert capstone and the second is the Associate one, over the same five wells.'),
  ('torquedrag', 'intermediate', 'module', 'm06-the-professional-reading', 10, 'Why does the capstone run at 1500 kg/m3 rather than the lessons'' 1440?', '["Because 1500 is a rounder number.", "Because at 1440 several of the wells buckle, which makes the graded answers ambiguous and difficult to reproduce.", "So that every graded value is one you produce rather than one a lesson printed.", "Because the goldens were generated at 1500, so grading at that value allows a direct comparison with the oracle."]'::jsonb, 2, 'It also asks a real question: what does a mud weight increase do to the torque and drag on a well already planned?'),
  ('torquedrag', 'intermediate', 'module', 'm06-the-professional-reading', 11, 'Which habit does this tier ask you to carry about the step?', '["Refine it once on anything you will rely on, and check the answer moved by less than you care about.", "Always use the finest available step.", "Use the default of 10 m, since the goldens were generated at that step and any other value breaks the comparison.", "Refine until the answer stops changing in the fourth significant figure, which is the precision of any report."]'::jsonb, 0, 'It is one extra run. It separates a number you have checked from a number you have not.'),
  ('torquedrag', 'intermediate', 'module', 'm06-the-professional-reading', 12, 'What is the other habit?', '["Fit both friction factors at once.", "Fit the friction factor daily, so that the trend rather than the value is what goes into the report.", "Fit against the torque rather than the hookload, since torque has the higher friction share on a deviated well.", "Fit one observation and predict another."]'::jsonb, 3, 'The daily-fit habit is good and it is the application. The cross-check is what makes any single fit worth reporting.'),
  ('torquedrag', 'intermediate', 'module', 'm06-the-professional-reading', 13, 'What does the Expert tier add?', '["A more accurate friction model.", "What the friction force does to the string and to the casing it rubs against.", "The dynamics the steady-state model omits, including stick-slip and the difference between static and kinetic friction.", "The hydraulics, since cuttings beds are the largest single thing the friction factor absorbs in this course."]'::jsonb, 1, 'The hydraulics are the next course in the module rather than the next tier of this one.'),
  ('torquedrag', 'intermediate', 'module', 'm06-the-professional-reading', 14, 'In one sentence, what is the Professional claim?', '["The model reproduces field hookloads.", "The friction factor is a material property of the rock, measured by back-analysis over thousands of wells.", "Every number the model produces is a checkable geometry times a fitted constant, and the discipline is knowing which is which.", "Torque and drag are two separate calculations that happen to use the same survey and the same string description."]'::jsonb, 2, 'The last of the wrong answers is what this tier''s second module spends five lessons disproving.'),
  ('torquedrag', 'intermediate', 'module', 'm06-the-professional-reading', 15, 'What is the friction share of surface torque on a deviated well, and why does it matter?', '["Around 83 to 90 percent, which is why torque is the better hole-condition indicator.", "About half, so both signals are equal.", "Nearly nothing, since the bit torque dominates and the friction along the string is a small correction to it.", "It depends on the rate of penetration, so no general statement is possible without knowing the bit''s performance."]'::jsonb, 0, 'The signal comes through a noisier instrument, which is why both are watched and a downhole measurement beats either.'),
  ('torquedrag', 'intermediate', 'final', null, 1, 'A report states a friction factor of 0.32 for a formation. What is wrong with the sentence?', '["Nothing, that is a normal value.", "Nobody measured it: it was fitted, in one hole, with one model, on one day.", "The value is too low for open hole in water-based mud, where the published range starts at about 0.25.", "A friction factor should be quoted to three decimals, since the fit is deterministic to machine precision."]'::jsonb, 1, 'It is not transferable to a different hole in the same rock without saying so, and not to different software at all.'),
  ('torquedrag', 'intermediate', 'final', null, 2, 'A well is switched from water-based to oil-based mud. What happens to the fitted factor?', '["It falls, often by a fifth or more, which can be the difference between a drillable well and one that is not.", "It rises, because oil is denser.", "It stays the same, since the friction factor describes the rock and the mud only changes the buoyancy.", "It becomes undefined, because the published typical values are quoted for water-based mud only."]'::jsonb, 0, 'The base oil lubricates the contact and the filter cake is thinner and firmer. That is why extended reach wells use it.'),
  ('torquedrag', 'intermediate', 'final', null, 3, 'A calibration on the horizontal well moves the fitted factor a lot when the cased value is changed. What does that say?', '["The calibration has converged well.", "The cased section carries most of the side force, so the cased factor should be the one fitted instead.", "The fit is poorly conditioned and the answer is not trustworthy.", "The two factors are correlated, which is expected, and the fitted value should be reported as a range."]'::jsonb, 2, 'If it barely moves the cased section is not contributing much and the assumption is harmless. Two runs tell you which.'),
  ('torquedrag', 'intermediate', 'final', null, 4, 'You have one pick-up hookload and two unknown friction factors. What do you do?', '["Fit both simultaneously.", "Take the ratio of the published typical values as a constraint, which reduces the problem to one unknown.", "Report the range of factor pairs that reproduce the observation, which is a line in the two-dimensional space.", "Hold one at a book value and fit the other, and say in the report which was held."]'::jsonb, 3, 'Better still, fit at two depths if a pre-shoe reading exists. What is not acceptable is reporting one number with no statement of what was fixed.'),
  ('torquedrag', 'intermediate', 'final', null, 5, 'A hookload fit gives a factor that predicts a torque 25 percent above the measured one. What do you check?', '["The mud weight.", "The tool joint diameters in the string description.", "The survey, since a missing section understates the side force and therefore the torque relative to the hookload.", "The rate of penetration, which sets the bit torque and therefore the on-bottom reading being compared."]'::jsonb, 1, 'Torque is proportional to the contact radius and hookload is nearly independent of it, so a blank tool joint column is 25 percent of torque and nothing else.'),
  ('torquedrag', 'intermediate', 'final', null, 6, 'Which of these is NOT caught by fitting hookload and predicting torque?', '["A missing stabiliser.", "A cuttings bed, which produces axial ploughing force and relatively less rotational resistance.", "A wrong mud weight.", "A blank tool joint diameter, which is a quarter of the torque and almost none of the hookload."]'::jsonb, 2, 'Mud weight scales both similarly, as does a survey error that scales the whole side force. The test is a filter, not a proof.'),
  ('torquedrag', 'intermediate', 'final', null, 7, 'Why is torque a better hole-condition indicator than hookload on a long well?', '["Because a much larger share of it is friction rather than weight.", "Because it is measured more accurately.", "Because it accumulates from the bit upward, whereas hookload includes the weight of everything below the top drive.", "Because it is measured at the top drive, which is closer to the string than the weight indicator on the travelling block."]'::jsonb, 0, 'Around 83 to 90 percent of a deviated well''s surface torque is friction, and the signal comes through a noisier instrument.'),
  ('torquedrag', 'intermediate', 'final', null, 8, 'A driller records off-bottom torque at every connection. What is that reading for?', '["It is a safety check on the top drive.", "It is the reading the model predicts most accurately, because the bit''s contribution is known exactly at 2700 N.m.", "It is a measure of how much of the torque the bit is consuming, obtained by subtracting it from the on-bottom value.", "It is pure friction, with no bit torque in it, so it is the right thing to calibrate against."]'::jsonb, 3, 'An on-bottom torque contains a bit torque that depends on the bit, the formation, the weight on bit and the penetration rate.'),
  ('torquedrag', 'intermediate', 'final', null, 9, 'You have a 4000 m lateral. Where would you expect the side force per metre to be largest?', '["At the toe of the lateral.", "In the build above the lateral, if the string is under tension there.", "Evenly along the lateral, since every metre of it contributes the same buoyed weight against the low side.", "At the heel, where the well transitions from build to lateral and the curvature is highest in the whole well."]'::jsonb, 1, 'The lateral''s per-metre force is uniform and moderate. The build''s peak is where a tensioned string is pulled around a corner.'),
  ('torquedrag', 'intermediate', 'final', null, 10, 'A well is planned with the build moved 800 m deeper. What happens to the side force there?', '["It falls, because the string is shorter.", "It is unchanged, since the curvature is the same and the side force depends on curvature rather than depth.", "It rises, because the whole extra string above now pulls through the same curvature.", "It falls, because the deeper hole is smaller and the tighter clearance reduces the contact force."]'::jsonb, 2, 'That is why the standard extended reach prescription is build early, build gently, hold long.'),
  ('torquedrag', 'intermediate', 'final', null, 11, 'What does a 10 degree azimuth turn cost in curvature at 5 degrees of inclination?', '["Less than a 1 degree build, because the sine of 5 degrees is under a tenth.", "The full 10 degrees.", "Half of it, since at low inclination the horizontal and vertical components of the change are comparable.", "Nothing at all, because azimuth is not defined near vertical and the term is excluded below a threshold."]'::jsonb, 0, 'At 90 degrees the same turn costs the full amount, and it costs it in the lateral direction that anti-collision cares about most.'),
  ('torquedrag', 'intermediate', 'final', null, 12, 'Why is a three-dimensional turn cheaper than a build followed by a turn?', '["Because it takes less measured depth.", "The two curvatures are perpendicular, so they combine in quadrature rather than adding.", "Because the azimuth term is scaled by the sine of inclination, which is smaller during a simultaneous build.", "Because the assembly can hold a constant toolface, which produces a smoother hole than two sequential sections."]'::jsonb, 1, 'Doing them in sequence produces two curvatures in series. Doing them together produces one whose magnitude is the quadrature sum.'),
  ('torquedrag', 'intermediate', 'final', null, 13, 'A sweep of pick-up hookload against friction factor comes out perfectly straight. What does that mean?', '["The model has a linearisation bug.", "The friction factor is not affecting the answer, since a linear response indicates a constant of proportionality of zero.", "The string is in compression along its length, which removes the tension term from the side force expression.", "The tension-to-side-force feedback is weak on that geometry."]'::jsonb, 3, 'On a longer, more deviated well the same table curves upward, and on the same well''s slack-off column it already does.'),
  ('torquedrag', 'intermediate', 'final', null, 14, 'Which response is better behaved for calibration, pick up or slack off?', '["Slack off, being smaller.", "Neither: both are equally well conditioned, and the choice is made on which reading is recorded more reliably.", "Pick up, because slack off goes nonlinear once compression starts.", "Slack off, because friction contributes a larger fraction of it and the fit is therefore more sensitive."]'::jsonb, 2, 'Friction is a larger fraction of the swing on slack off and the response''s nonlinearity outweighs it.'),
  ('torquedrag', 'intermediate', 'final', null, 15, 'How do you decide whether the cased-hole friction factor matters on a given well?', '["Look at where the side force is: a factor multiplying zero side force contributes nothing.", "Compare the two section lengths.", "Compare the two published typical values, since the difference between them bounds the possible effect.", "Run the model twice at the extremes of the cased range and take the difference as the sensitivity."]'::jsonb, 0, 'Running it twice is the confirmation and looking at the profile is the one-minute version that tells you why.'),
  ('torquedrag', 'intermediate', 'final', null, 16, 'A model at 120 rpm and 0.3 m/s puts about a quarter of the friction axially. What sets that?', '["The friction factor.", "The ratio of the tool joint''s surface speed to the trip speed.", "The buoyancy factor, which sets how much of the string''s weight is available to press against the wall.", "The inclination, which sets how much of the weight acts perpendicular to the hole and therefore in contact."]'::jsonb, 1, 'At 120 rpm the surface speed is about 1.06 m/s against a trip speed of 0.3, and the shares follow directly.'),
  ('torquedrag', 'intermediate', 'final', null, 17, 'You want to maximise the drag reduction from back reaming. What do you do?', '["Pull faster and rotate slower.", "Rotate slower, which reduces the tangential velocity and therefore the torque the operation costs.", "Increase the weight on bit, which raises the side force and therefore the friction available to redirect.", "Pull slower, so the axial share falls further."]'::jsonb, 3, 'Rotating slower moves friction back into the axial direction, which is the wrong way. Pulling slower also takes longer.'),
  ('torquedrag', 'intermediate', 'final', null, 18, 'A torque profile shows a step at a depth with no bit and no motor. What is it?', '["A change in hole section.", "A change in the string''s composition, where the tool joint radius changes and the accumulation rate steps with it.", "An input error, since only an applied moment can step the torque.", "A dogleg, where the sudden change in curvature produces a step in the side force and therefore in the torque."]'::jsonb, 2, 'A composition change or a dogleg steps the RATE of accumulation, which is a kink rather than a step in the value.'),
  ('torquedrag', 'intermediate', 'final', null, 19, 'Which two things scale the torque a metre of lateral contributes?', '["The buoyed weight per metre and the tool joint radius, times the friction factor.", "The tension and the curvature.", "The rotary speed and the trip speed, through the two direction cosines that split the friction.", "The hole diameter and the pipe diameter, which together set the radial clearance the string moves in."]'::jsonb, 0, 'In a straight lateral there is no curvature and the tension does not enter the side force at all.'),
  ('torquedrag', 'intermediate', 'final', null, 20, 'A colleague says rotating reduces friction. Correct them.', '["Rotation does reduce total friction.", "It redirects it: the sum of the squares of the two shares is one, so the total is conserved.", "It reduces the normal force, because a rotating string rides up the side of the hole and presses less hard.", "It reduces the friction factor, because a moving contact has a lower coefficient than a stationary one."]'::jsonb, 1, 'The static-to-kinetic distinction is real and is not in this model. What the model does is move friction between two directions.'),
  ('torquedrag', 'intermediate', 'final', null, 21, 'What would you conclude from a hookload that matches the model and a torque 20 percent above it?', '["The friction factor is 20 percent low.", "The mud weight is wrong, since it scales the weight and therefore both the hookload and the torque together.", "The hole is dirty, since a cuttings bed produces rotational resistance without changing the axial load.", "Something with a large contact radius that the string description does not have."]'::jsonb, 3, 'A dirty hole gives the opposite signature: hookload high and torque normal. Torque high alone points at a radius.'),
  ('torquedrag', 'intermediate', 'final', null, 22, 'Why does the goldens file exist rather than a published worked example?', '["Because the published examples are proprietary.", "Because published examples use imperial units, and converting them would introduce a rounding error into the check.", "Because the soft-string model has no closed form on a real survey.", "Because a published example would only cover one geometry, whereas the goldens cover five different wells."]'::jsonb, 2, 'The five-geometry point is a real benefit and it is not the reason. There is simply nothing to check by hand.'),
  ('torquedrag', 'intermediate', 'final', null, 23, 'What is the value of an independent implementation as a check?', '["It eliminates transcription, sign, unit and misread-formula errors, which are most defects that occur.", "It validates the physics.", "It bounds the discretisation error, since two schemes of different order bracket the true answer between them.", "It confirms the friction factors used are appropriate, since a wrong factor would show as a disagreement."]'::jsonb, 0, 'It says nothing about whether the equations describe a drill string, because both implementations share the same assumptions.'),
  ('torquedrag', 'intermediate', 'final', null, 24, 'The worst relative disagreement with the oracle is on a case flagged as buckled. What follows?', '["The engine has a defect there.", "Both implementations are computing a number that does not describe anything real.", "The oracle handles buckling correctly and the engine does not, which is why they diverge in that regime.", "The disagreement should be excluded from the comparison, since a buckled case is outside the model''s scope."]'::jsonb, 1, 'Excluding it would be dishonest. Reporting it with the buckling flag attached is what makes the statement usable.'),
  ('torquedrag', 'intermediate', 'final', null, 25, 'A gap against an oracle halves when the step halves. What is it?', '["A model difference.", "A rounding error, which accumulates over the number of intervals and therefore scales with the step.", "An input difference, since a finer grid samples the survey at different depths than a coarse one.", "Discretisation, and the two implementations agree in the limit."]'::jsonb, 3, 'A model difference stops moving when the step is refined, which is exactly what the slant well shows.'),
  ('torquedrag', 'intermediate', 'final', null, 26, 'A gap against an oracle stops moving under refinement. Which is closer to the truth?', '["The finer-stepped one.", "The one with the higher-order integration scheme, since its truncation error falls faster and its limit is better.", "Refinement cannot say; a case with a closed form can.", "Neither: two convergent schemes on the same equations must reach the same limit, so the gap must be an input difference."]'::jsonb, 2, 'Both are converging, on slightly different answers. Only a third source settles it.'),
  ('torquedrag', 'intermediate', 'final', null, 27, 'What does the vertical well establish about the two implementations?', '["The engine reproduces the closed form to nanonewtons; the oracle is tens of newtons away.", "Both reproduce it exactly.", "The oracle reproduces it exactly and the engine is a few nanonewtons off, which is floating-point noise.", "Neither reproduces it, because the closed form ignores the buckling flag the model raises in that case."]'::jsonb, 0, 'That is why the residual on the other wells is most likely the oracle''s own integration rather than the engine''s.'),
  ('torquedrag', 'intermediate', 'final', null, 28, 'Why is the vertical case not a complete answer to the disagreement?', '["Because it is only one well.", "It never touches the friction, curvature or direction-cosine terms.", "Because a closed form on a degenerate case cannot be extended to the general case by any argument.", "Because the oracle was not designed to handle a well with no side force, so its result there is not representative."]'::jsonb, 1, 'It settles the residual only if the residual comes from the weight integral, which is plausible and is not proved.'),
  ('torquedrag', 'intermediate', 'final', null, 29, 'Which observation would you record before drilling out a shoe, and why?', '["A torque reading, for the bit torque.", "A slack-off hookload, because it is the most sensitive of the three to the friction in the cased section.", "All three hookloads, because their differences are what carry the information about the cased section''s condition.", "A pick-up hookload, because it fixes the cased-hole friction factor on its own."]'::jsonb, 3, 'It costs nothing and it converts an under-determined two-factor fit into a determined one.'),
  ('torquedrag', 'intermediate', 'final', null, 30, 'What does a fitted friction factor need reported alongside it?', '["The hookload it was fitted to.", "The published typical range for that hole condition, so a reader can see whether the value is plausible.", "The model, the software, the survey, the string description and the date.", "The confidence interval, obtained by refitting at the extremes of the hookload measurement''s uncertainty."]'::jsonb, 2, 'It is the same list an uncertainty ellipse needs in the survey course, and for the same reason: a fitted parameter needs its fit.'),
  ('torquedrag', 'intermediate', 'final', null, 31, 'Which is the best available number for planning the next well in a field?', '["A factor fitted on the last well, drilled with the same model and software in a similar geometry.", "The published book value.", "The average of every factor ever fitted in that field, which averages out the well-specific effects.", "A factor fitted on the deepest well in the field, since it covers the largest range of hole conditions."]'::jsonb, 0, 'Book values are for when there is no fitted value. A fitted value from THIS well beats both, once there is one.'),
  ('torquedrag', 'intermediate', 'final', null, 32, 'Why does the moment arm appear twice in the calculation?', '["It appears only once.", "As the lever for the torque, and inside the tangential velocity that sets the direction cosines.", "As the lever for the torque, and in the radial clearance that sets the buckling limits for that component.", "Once for the tool joint and once for the pipe body, since both are in contact over part of each joint."]'::jsonb, 1, 'The two effects are in the same direction for torque and in opposite directions for hookload, which is why hookload barely moves.'),
  ('torquedrag', 'intermediate', 'final', null, 33, 'Going on bottom raises the torque by less than the bit torque on three of five wells. Why?', '["The bit torque is partly absorbed.", "The rotary speed falls when weight is applied, which changes the tangential share of the friction.", "The engine applies the bit torque as a boundary condition rather than adding it to the surface value.", "The compression it adds reduces the side force in the curved sections near the bit."]'::jsonb, 3, 'On the horizontal well the effect reverses and the torque rises by more, because a buckling string presses outward.'),
  ('torquedrag', 'intermediate', 'final', null, 34, 'What is the model''s treatment of trip speed, and why is it a limitation?', '["It scales the friction linearly.", "It is not used at all, since the model is a steady state and the speed cancels out of the equations.", "It enters only the direction cosines, so with no rotation the drag does not depend on it at all.", "It enters the buckling check, since a faster trip applies compression more quickly than the pipe can redistribute."]'::jsonb, 2, 'Real friction has a velocity dependence, and surge and swab pressures are strongly speed dependent. Neither is here.'),
  ('torquedrag', 'intermediate', 'final', null, 35, 'What is the effect of holding the string stationary, in the model?', '["Zero friction, so the hookload is the free-hanging weight.", "The maximum friction.", "An undefined result, since both direction cosines become zero over zero and the engine returns not-a-number.", "The same as the previous operation, since the model carries the state from the last computed condition."]'::jsonb, 0, 'That is a convention rather than physics, and the gap between it and static friction is what a driller feels when a string will not break over.'),
  ('torquedrag', 'intermediate', 'final', null, 36, 'A cuttings bed presents as a friction factor. Why is that a fiction that works?', '["Cuttings genuinely raise the coefficient.", "The bed adds to the buoyed weight of the string, which raises the side force and therefore the friction proportionally.", "The bed reduces the effective hole diameter, which raises the contact pressure and therefore the friction factor.", "The ploughing force is not proportional to normal force, but putting it in the factor reproduces the hookload."]'::jsonb, 3, 'It presents as a factor rising with penetration rate and falling on circulation, which is not how a coefficient of friction behaves.'),
  ('torquedrag', 'intermediate', 'final', null, 37, 'Which of these distinguishes differential sticking from a cuttings bed?', '["Sticking is depth-specific.", "Sticking rises with stationary time; a bed rises with penetration rate.", "Sticking affects only the torque, since the clamping force acts perpendicular to the axis of the string.", "A bed appears only in cased hole, where the annular velocity is lowest and the cuttings settle out."]'::jsonb, 1, 'Depth-specific behaviour is a ledge or a keyseat, and following the assembly''s position rather than a depth is stiffness.'),
  ('torquedrag', 'intermediate', 'final', null, 38, 'What is the practical value of the friction factor''s TREND?', '["It measures the rock''s roughness.", "It bounds the model''s error, since a stable factor indicates that the omitted physics is not contributing.", "It summarises everything the model cannot see, so a change in it is a change in the hole.", "It converges toward the true coefficient of friction as more observations are collected over the well."]'::jsonb, 2, 'That is exactly why a rising factor is one of the most useful signals on a rig even though the value is not a material property.'),
  ('torquedrag', 'intermediate', 'final', null, 39, 'You are asked to reduce the surface torque on a planned lateral. What are your levers?', '["The friction factor through mud and subs, the pipe''s contact radius, and not sliding.", "A lower rotary speed.", "A heavier mud, which raises the buoyancy factor and reduces the string''s weight against the low side.", "A finer integration step, which resolves the section boundaries more accurately and lowers the computed torque."]'::jsonb, 0, 'A heavier mud reduces the buoyed weight and therefore the side force, so it does help, and it also raises the equivalent circulating density.'),
  ('torquedrag', 'intermediate', 'final', null, 40, 'What is the correct reading of a step study that moves the answer by a kilonewton?', '["The model is wrong.", "The default step is too coarse for that case, and the answer at 10 m should not be relied on.", "The oracle is wrong, since the engine is converging and the oracle''s value is the fixed reference being compared against.", "The friction factor should be refitted at the finer step, since the fit was done against a coarse-step forward run."]'::jsonb, 1, 'The refitting point is a real consequence if a calibration was done at the coarse step, and it follows from the first.'),
  ('torquedrag', 'intermediate', 'final', null, 41, 'Which of the six operations does not depend on the friction factor at all?', '["Rotating off bottom.", "Tripping out and tripping in, since with no rotation the tangential friction vanishes and the axial part is pure weight.", "Sliding, since the surface torque is exactly the bit torque regardless of what the friction factor is set to.", "None of them, though rotating off bottom''s HOOKLOAD does not."]'::jsonb, 3, 'Rotating off bottom''s hookload is the free-hanging weight whatever the factor, and its TORQUE depends on the factor entirely.'),
  ('torquedrag', 'intermediate', 'final', null, 42, 'What is the honest one-line summary of a calibrated torque and drag model?', '["It measures the friction in the hole.", "It predicts the hookload and torque to within a few percent, which is the accuracy the goldens comparison establishes.", "It reproduces one observation exactly and predicts the others as well as its assumptions allow.", "It is validated against an independent implementation, so its answers can be relied on within the stated tolerance."]'::jsonb, 2, 'The goldens comparison is verification rather than validation, and it says nothing about how well the model matches a real well.');
